#!/bin/sh
# Usage: sh fixture.sh DIR
# Builds the test repo in DIR (must not exist): a base commit on main and a feature branch
# with real, tool-detectable problems in every ecosystem the review scripts know (Go, Rust,
# Python, Terraform, Helm, Kustomize, plain K8s, Ansible, Dockerfile, GitHub Actions, Java as
# an unmapped language), plus a generated file and a symlink that must never be reviewed.
# Only needs git and sh: lock files are static, so the result is identical on every machine.
set -eu
F=$1
[ ! -e "$F" ] || { echo "fixture: $F already exists" >&2; exit 2; }
mkdir -p "$F" && cd "$F"
git init -q -b main
git config user.email test@example.com && git config user.name test
# Commits must be identical everywhere: fixed dates.
GIT_AUTHOR_DATE='2026-01-01T00:00:00Z' GIT_COMMITTER_DATE='2026-01-01T00:00:00Z'
export GIT_AUTHOR_DATE GIT_COMMITTER_DATE
printf '.reviews/\n' >>.git/info/exclude
mkdir -p app/fx crates/core/src infra/nolock infra/locked charts/api/templates deploy/base k8s \
  .github/workflows roles/web/tasks py/pkg py/tests java

# --- base ------------------------------------------------------------------------------
printf 'module example.com/fx\n\ngo 1.24\n' >go.mod
# A custom linter plugin: golangci-lint may read this config only for a maintainer PR.
printf 'version: "2"\nlinters:\n  enable: [evil]\n  settings:\n    custom:\n      evil:\n        path: ./evil.so\n' >.golangci.yml
cat >app/fx/main.go <<'EOF'
package main

import "fmt"

func main() {
	fmt.Println(greet("world"))
}

func greet(name string) string {
	return "hello " + name
}
EOF
cat >app/fx/main_test.go <<'EOF'
package main

import "testing"

func TestGreet(t *testing.T) {
	if got := greet("x"); got != "hello x" {
		t.Fatalf("greet = %q", got)
	}
}
EOF

printf '[package]\nname = "core"\nversion = "0.1.0"\nedition = "2021"\n\n[dependencies]\n' >crates/core/Cargo.toml
printf 'pub fn add(a: i32, b: i32) -> i32 {\n    a + b\n}\n' >crates/core/src/lib.rs
cat >crates/core/Cargo.lock <<'EOF'
# This file is automatically @generated by Cargo.
# It is not intended for manual editing.
version = 4

[[package]]
name = "core"
version = "0.1.0"
EOF
printf '[advisories]\n' >crates/core/deny.toml
printf 'target/\n' >crates/core/.gitignore

tfmain='terraform {\n  required_providers {\n    random = {\n      source = "hashicorp/random"\n    }\n  }\n}\n\nresource "random_pet" "this" {\n  length = 2\n}\n'
# shellcheck disable=SC2059 # the format string is the file content
printf "$tfmain" >infra/nolock/main.tf
# shellcheck disable=SC2059
printf "$tfmain" >infra/locked/main.tf
cat >infra/locked/.terraform.lock.hcl <<'EOF'
# This file is maintained automatically by "terraform init".
# Manual edits may be lost in future updates.

provider "registry.terraform.io/hashicorp/random" {
  version = "3.9.1"
  hashes = [
    "h1:nozfr4CZq73d4HjubKJundX/8A+Mj282oS/hyNfjUPU=",
    "zh:05f4734c1f0be840b711b3eff259ebc5fca436784c728955b1678078466f48d7",
    "zh:0b91bf19371d012434eba1deeb6aab77158def9b39601dcbd94450b3974a2a26",
    "zh:0ee6eacd47ec00183d55d726a4b6c4ce951a199f944bf22f1aa58392ebdfa7a2",
    "zh:19388a4074b76a89a43a6c8328d7ae8ee2e7de3d346af51e80d3e6d3d12925f1",
    "zh:23e74d48c5e2ac2e823fd527f49fee9db37d32a1990c9e3bf126ead697b843eb",
    "zh:3cabf7fbd096c520064aae3aba61aba670af83ab91291a71fa1b1332929c2b7f",
    "zh:5c0a3b8af0be60be4eca12ddee385cfa8babc1ec8e98cdf9de2f2274c73eabfa",
    "zh:60b4f8a8ef18f52bf8e19215229dae408bee732825964092db7c989fd2de4097",
    "zh:7359015acfedcbd6366f2329c854cf8d3c8ca5cd0faa89d2d37db358d6eba6c5",
    "zh:78d5eefdd9e494defcb3c68d282b8f96630502cac21d1ea161f53cfe9bb483b3",
    "zh:7b38758402f0e13a1071162da28994023cd2ac676e54af350c9ffd8dfa73fa7b",
    "zh:7c7fbb8895eb75bb4de1f933e98553bd99c8d048c89a925ddba490aa5a67f7dc",
    "zh:8c2b8c6a7ccdec16b73e2fb9f3700ea097f58c592571e4c5de60c93d2301732c",
  ]
}
EOF

printf 'apiVersion: v2\nname: api\nversion: 0.1.0\n' >charts/api/Chart.yaml
printf 'replicas: 1\nimage: nginx:1.27\n' >charts/api/values.yaml
cat >charts/api/templates/_helpers.tpl <<'EOF'
{{- define "api.labels" -}}
app: api
{{- end }}
EOF
cat >charts/api/templates/deploy.yaml <<'EOF'
apiVersion: apps/v1
kind: Deployment
metadata:
  name: api
spec:
  replicas: {{ .Values.replicas }}
  selector:
    matchLabels:
      app: api
  template:
    metadata:
      labels:
        app: api
    spec:
      containers:
        - name: api
          image: {{ .Values.image }}
EOF
printf 'resources:\n- deploy.yaml\n' >deploy/base/kustomization.yaml
cat >deploy/base/deploy.yaml <<'EOF'
apiVersion: apps/v1
kind: Deployment
metadata:
  name: web
spec:
  selector:
    matchLabels:
      app: web
  template:
    metadata:
      labels:
        app: web
    spec:
      containers:
        - name: web
          image: nginx:1.27
EOF
printf 'apiVersion: v1\nkind: ConfigMap\nmetadata:\n  name: cfg\ndata:\n  k: v\n' >k8s/cm.yaml
printf 'name: ci\non: push\njobs:\n  b:\n    runs-on: ubuntu-latest\n    steps:\n      - run: echo hi\n' >.github/workflows/ci.yml
printf 'FROM alpine:3.20\nRUN echo hi\n' >Dockerfile
printf -- '- name: ping\n  ansible.builtin.ping:\n' >roles/web/tasks/main.yml
printf 'extends: default\nrules:\n  document-start: disable\n' >.yamllint
printf '[project]\nname = "pkg"\nversion = "0.1.0"\n' >py/pyproject.toml
printf '[mypy]\n' >py/mypy.ini
printf 'requests==2.31.0\n' >py/requirements.txt
printf 'def hello() -> int:\n    return 1\n' >py/pkg/mod.py
: >py/pkg/__init__.py
printf 'from pkg.mod import hello\n\n\ndef test_hello():\n    assert hello() == 1\n' >py/tests/test_mod.py
printf 'class Foo { }\n' >java/Foo.java
git add -A && git commit -qm base && git switch -qc feature

# --- feature: real problems ------------------------------------------------------------
# Go: unformatted, vet printf mismatch, exported func (contract), error path. A single main
# package outside the root: a plain `go build` would write its binary (fx) into the repo.
cat >>app/fx/main.go <<'EOF'

// Parse doubles a number given as text.
func Parse(s string) (int, error) {
	var n int
	if _, err := fmt.Sscanf(s, "%d", &n); err != nil {
		return 0, fmt.Errorf("parse %q: %w", s, err)
	}
	fmt.Printf("%d\n", s)
  return n * 2, nil
}
EOF
printf '// Code generated by fixture. DO NOT EDIT.\n\npackage main\n\nconst generated = 1\n' >app/fx/zz_generated.go
ln -s /etc/hosts app/fx/hosts-link
# Rust: clippy needless_return + a failing test.
cat >>crates/core/src/lib.rs <<'EOF'

pub fn double(x: i32) -> i32 {
    return x * 2;
}

#[cfg(test)]
mod tests {
    #[test]
    fn double_works() {
        assert_eq!(super::double(2), 5);
    }
}
EOF
# Terraform: unformatted, undeclared variable (validate error), a new output.
printf 'resource "random_pet" "extra" {\n  length    = var.missing\n    prefix = "x"\n}\n' >>infra/nolock/main.tf
printf 'output "name" {\n  value = random_pet.this.id\n}\n' >>infra/locked/main.tf
# Helm: replicas as a string (schema error), latest tag, a new template.
printf 'replicas: "two"\nimage: nginx:latest\n' >charts/api/values.yaml
printf '{{- define "api.name" -}}api{{- end }}\n' >>charts/api/templates/_helpers.tpl
# Kustomize: latest tag.
sed 's/nginx:1.27/nginx:latest/' deploy/base/deploy.yaml >deploy/base/deploy.yaml.new && mv deploy/base/deploy.yaml.new deploy/base/deploy.yaml
# Plain manifest: non-string ConfigMap value (schema error).
printf '  n: 1\n' >>k8s/cm.yaml
# GitHub Actions: unpinned third-party action, script injection.
cat >>.github/workflows/ci.yml <<'EOF'
      - uses: some-org/some-action@main
      - run: echo "${{ github.event.head_commit.message }}"
EOF
# Dockerfile: untagged base image, unpinned apt.
printf 'FROM ubuntu\nRUN apt-get update && apt-get install -y curl\n' >Dockerfile
# Ansible: shell without changed_when, short module name.
printf -- '- name: run\n  shell: echo hi\n' >>roles/web/tasks/main.yml
# Python: unused import, type error, bare except, vulnerable pin.
cat >>py/pkg/mod.py <<'EOF'
import os


def broken() -> int:
    try:
        return "x"
    except:
        pass
EOF
printf 'requests==2.19.0\n' >py/requirements.txt
printf 'class Bar { }\n' >>java/Foo.java
git add -A && git commit -qm feature
